1	// Package contractsentinel implements audit rule evaluation over contract artifacts.
2	package contractsentinel
3	
4	import "sort"
5	
6	// Artifact is one compiled contract target under audit.
7	type Artifact struct {
8		Name     string
9		ABI      string
10		Bytecode string
11		Source   string
12	}
13	
14	// Finding is one rule violation with the invariant it breaks.
15	type Finding struct {
16		Rule      string
17		Severity  string
18		Invariant string
19		Evidence  string
20	}
21	
22	// Rule is a static or symbolic check the pipeline can run.
23	type Rule struct {
24		ID          string
25		Kind        string
26		Severity    string
27		Invariant   string
28		RequiresABI bool
29		Version     string
30	}
31	
32	// Run executes the deterministic subset of rules and refuses inputs they need.
33	func Run(artifact Artifact, rules []Rule, invariants map[string]bool) ([]Finding, error) {
34		if artifact.Name == "" {
35			return nil, errInvalid("artifact name is required")
36		}
37		var findings []Finding
38		for _, rule := range rules {
39			if rule.RequiresABI && artifact.ABI == "" {
40				return nil, errInvalid("rule " + rule.ID + " needs an ABI")
41			}
42			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
43				return nil, errInvalid("symbolic rule " + rule.ID + " needs bytecode")
44			}
45			if holds, checked := invariants[rule.Invariant]; checked && !holds {
46				findings = append(findings, Finding{Rule: rule.ID, Severity: rule.Severity,
47					Invariant: rule.Invariant, Evidence: "invariant " + rule.Invariant + " does not hold"})
48			}
49		}
50		sort.Slice(findings, func(i, j int) bool {
51			if findings[i].Severity == findings[j].Severity {
52				return findings[i].Rule < findings[j].Rule
53			}
54			return findings[i].Severity > findings[j].Severity
55		})
56		return findings, nil
57	}
58	
59	type errInvalid string
60	
61	func (e errInvalid) Error() string { return string(e) }
62

