262		if _, _, _, _, err := ParseAuditInput(data); err != nil {
263			t.Fatalf("a single unknown field must stay accepted: %v", err)
264		}
265	}
266	
267	func TestParseAuditInputLegalFalseTrueUnchanged(t *testing.T) {
268		// 合法 false 仍是缺陷、合法 true 仍是通过：端到端报告状态不变。
269		artifact := Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
270		rules := []Rule{
271			{ID: "r-fail", Kind: "static", Severity: "high", Invariant: "inv-fail", Version: "1"},
272			{ID: "r-pass", Kind: "static", Severity: "low", Invariant: "inv-pass", Version: "1"},
273		}
274		invariants := map[string]bool{"inv-fail": false, "inv-pass": true}
275		report, err := BuildReport(artifact, rules, invariants, nil)
276		if err != nil {
277			t.Fatal(err)
278		}
279		status := map[string]string{}
280		for _, r := range report.Rules {
281			status[r.ID] = r.Status
282		}
283		if status["r-fail"] != StatusDefect || status["r-pass"] != StatusPass {
284			t.Fatalf("legal false/true conclusions changed: %+v", status)
285		}
286		if len(report.Findings) != 1 || report.Findings[0].RuleID != "r-fail" {
287			t.Fatalf("exactly the false invariant must produce one defect: %+v", report.Findings)
288		}
289	}
