package main

import (
	"bytes"
	"encoding/json"
	"fmt"
)

// prototype of validateJSONCharacters
type charError struct{ msg string }
func (e *charError) Error() string { return e.msg }

type pathStep struct {
	key   string
	index int
}

func validate(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var scan func(path []pathStep) error
	scan = func(path []pathStep) error {
		for dec.More() {
			kStart := dec.InputOffset()
			kt, err := dec.Token()
			if err != nil {
				return nil // malformed: defer to Unmarshal
			}
			kEnd := dec.InputOffset()
			key, _ := kt.(string)
			if perr := checkString(data[kStart:kEnd], append(path, pathStep{key: key, index: -1})); perr != nil {
				return perr
			}
			vStart := dec.InputOffset()
			vt, err := dec.Token()
			if err != nil {
				return nil
			}
			vEnd := dec.InputOffset()
			switch v := vt.(type) {
			case string:
				if perr := checkString(data[vStart:vEnd], path); perr != nil {
					return perr
				}
				_ = v
			case json.Delim:
				if v == '{' {
					if e := scan(append(path, pathStep{key: key, index: -1})); e != nil {
						return e
					}
				} else if v == '[' {
					if e := scanArray(path, key, scan); e != nil {
						return e
					}
				}
			}
		}
		if _, err := dec.Token(); err != nil {
			return nil
		}
		return nil
	}
	scanArray = func(path []pathStep, key string, scan func([]pathStep) error) error {
		return nil
	}
	return nil
}

var scanArray func([]pathStep, string, func([]pathStep) error) error

func checkString(raw []byte, path []pathStep) error {
	if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
		return &charError{fmt.Sprintf("internal: bad raw slice %q", raw)}
	}
	body := raw[1 : len(raw)-1]
	if !utf8Valid(body) {
		return &charError{"invalid UTF-8"}
	}
	return nil
}

func utf8Valid(b []byte) bool { return true }

func main() {
	for _, in := range []string{
		`{"a":"x","b":{"c":[1,2,{"d":"y"}]},"e":"z"}`,
		`{"a":"x", "b" : [1,2]}`,
		` [1,{"a":"x"}] `,
		`"top scalar"`,
		`[["nested"]]`,
	} {
		data := []byte(in)
		dec := json.NewDecoder(bytes.NewReader(data))
		dec.UseNumber()
		var walk func(depth int) error
		var slices []string
		walk = func(depth int) error {
			for dec.More() {
				s := dec.InputOffset()
				t, err := dec.Token()
				e := dec.InputOffset()
				if err != nil { return err }
				if str, ok := t.(string); ok {
					slices = append(slices, fmt.Sprintf("STR key?%v %q", false, data[s:e]))
					_ = str
				}
				if d, ok := t.(json.Delim); ok && (d == '{' || d == '[') {
					if err := walk(depth+1); err != nil { return err }
				}
			}
			_, err := dec.Token()
			return err
		}
		_ = walk
		// uniform token dump
		var dump func()
		dump = func() {
			for dec.More() {
				s := dec.InputOffset()
				t, err := dec.Token()
				e := dec.InputOffset()
				if err != nil { fmt.Println("ERR", err); return }
				if str, ok := t.(string); ok {
					slices = append(slices, fmt.Sprintf("%q@%d:%d", str, s, e))
				}
				if d, ok := t.(json.Delim); ok && (d == '{' || d == '[') {
					dump()
				}
			}
			dec.Token()
		}
		dump()
		fmt.Printf("%-40s -> %v\n", in, slices)
	}
}
EOF
