// Package contractsentinel jsonchars: whole-document validation of the
// character legality of a JSON submission.
//
// encoding/json decodes two classes of illegal input without an error and
// silently rewrites the text: an invalid UTF-8 byte inside a JSON string and
// an unpaired (or wrongly ordered) UTF-16 surrogate escape are both replaced
// by U+FFFD. A check note carrying an isolated "\uD800" would therefore build
// a "successful" report whose evidence no longer matches the submitted bytes,
// and a source string hit by the same rewrite would change the content that
// feeds the artifact hash. The scan below re-inspects every raw JSON string
// literal — member names and string values, at every depth, including members
// dropped later as extension data — and rejects the whole submission with a
// precise location instead of letting any character be deleted or replaced.
package contractsentinel

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// charPathStep locates one JSON value, the same schema-free convention as
// dupPathStep: a member step or an array-index step.
type charPathStep struct {
	key   string // member name for an object step; "" for an array step
	index int    // 0-based array index for an array step; -1 for a member step
}

// charEncodingError is a character-legality rejection: invalid UTF-8 or an
// illegal Unicode escape. offset is the 0-based byte offset of the bad byte
// or the offending "\u" in the document; line and column locate it for the
// submitter.
type charEncodingError struct {
	problem string // what is wrong, e.g. "unpaired high surrogate escape \\uD800"
	where   string // "member name" or "string value"
	path    []charPathStep
	offset  int
	line    int
	column  int
}

func (e *charEncodingError) Error() string {
	return fmt.Sprintf("%s in JSON %s at %s (byte offset %d, line %d, column %d)",
		e.problem, e.where, renderCharPath(e.path), e.offset, e.line, e.column)
}

// renderCharPath renders the location as ".key[index].key"; an empty path is
// the top-level value.
func renderCharPath(path []charPathStep) string {
	if len(path) == 0 {
		return "the top-level value"
	}
	var b strings.Builder
	for _, step := range path {
		if step.index >= 0 {
			fmt.Fprintf(&b, "[%d]", step.index)
		} else {
			b.WriteByte('.')
			b.WriteString(step.key)
		}
	}
	return b.String()
}

// validateJSONCharacters scans every string literal in data — member names
// and string values, including those nested under unknown extension members —
// and returns the first invalid UTF-8 byte or illegal surrogate escape. It
// returns nil for malformed JSON: json.Unmarshal remains the single source of
// syntax errors and runs right after this scan, mirroring
// findDuplicateJSONMember.
func validateJSONCharacters(data []byte) *charEncodingError {
	dec := json.NewDecoder(bytes.NewReader(data))
	// Keep number literals as text; their bytes are never string content.
	dec.UseNumber()
	start := 0
	tok, err := dec.Token()
	if err != nil {
		return nil // malformed JSON: defer to json.Unmarshal
	}
	end := int(dec.InputOffset())
	switch v := tok.(type) {
	case string:
		return checkRawJSONString(data[start:end], data, nil, false)
	case json.Delim:
		if v == '{' {
			return scanCharObject(dec, data, nil)
		}
		if v == '[' {
			return scanCharArray(dec, data, nil)
		}
	}
	return nil
}

// scanCharObject scans one JSON object whose opening brace was just consumed.
func scanCharObject(dec *json.Decoder, data []byte, path []charPathStep) *charEncodingError {
	for dec.More() {
		keyStart := int(dec.InputOffset())
		keyTok, err := dec.Token()
		if err != nil {
			return nil // malformed JSON: defer
		}
		keyEnd := int(dec.InputOffset())
		key, _ := keyTok.(string)
		memberPath := append(append([]charPathStep(nil), path...), charPathStep{key: key, index: -1})
		// The member name itself is a JSON string and must be legal even when
		// the member is an unknown extension that never reaches the decoder.
		if e := checkRawJSONString(data[keyStart:keyEnd], data, memberPath, true); e != nil {
			return e
		}
		valStart := int(dec.InputOffset())
		valTok, err := dec.Token()
		if err != nil {
			return nil // malformed JSON: defer
		}
		valEnd := int(dec.InputOffset())
		switch v := valTok.(type) {
		case string:
			if e := checkRawJSONString(data[valStart:valEnd], data, memberPath, false); e != nil {
				return e
			}
		case json.Delim:
			if v == '{' {
				if e := scanCharObject(dec, data, memberPath); e != nil {
					return e
				}
			} else if v == '[' {
				if e := scanCharArray(dec, data, memberPath); e != nil {
					return e
				}
			}
		}
	}
	if _, err := dec.Token(); err != nil { // consume '}'
		return nil // malformed JSON: defer
	}
	return nil
}

// scanCharArray scans one JSON array whose opening bracket was just consumed.
func scanCharArray(dec *json.Decoder, data []byte, path []charPathStep) *charEncodingError {
	for i := 0; dec.More(); i++ {
