cat > contractsentinel/zz_edge_test.go <<'EOF'
package contractsentinel

import "testing"

func TestZZEdgeVariants(t *testing.T) {
	// lowercase hex digits
	if e := validateJSONCharacters([]byte(`{"a":"𐀀"}`)); e != nil {
		t.Fatalf("lowercase paired escape must be legal: %v", e)
	}
	if e := validateJSONCharacters([]byte(`{"a":"\ud800x"}`)); e == nil {
		t.Fatal("lowercase lone high must be rejected")
	}
	// pair split by an intervening escaped newline
	if e := validateJSONCharacters([]byte(`{"a":"\uD800\n\uDE00"}`)); e == nil {
		t.Fatal("high and low separated by another escape must be unpaired")
	}
	// surrogate as invariant name (value context)
	if e := validateJSONCharacters([]byte(`{"invariants":{"\uD800":true}}`)); e == nil {
		t.Fatal("lone surrogate in invariant name must be rejected")
	}
	// legal escapes still legal
	for _, in := range []string{
		`{"a":"tab\there"}`,
		`{"a":"quote\"end"}`,
		`{"a":"\/\b\f\r\t"}`,
		`{"a":"Aé"}`,
	} {
		if e := validateJSONCharacters([]byte(in)); e != nil {
			t.Errorf("legal input rejected %q: %v", in, e)
		}
	}
	// one bad check record among legal siblings rejects the whole input
	// (behavior at ParseAuditInput level)
	good := Artifact{Name: "V", ABI: "a", Bytecode: "0x1", Source: "s"}
	h := ArtifactHash(good)
	doc := []byte(`{
		"artifact":{"name":"V","abi":"a","bytecode":"0x1","source":"s"},
		"rules":[{"id":"r1","kind":"static","severity":"high","invariant":"i1","version":"1"},
		         {"id":"r2","kind":"static","severity":"low","invariant":"i2","version":"1"}],
		"checks":[
		  {"artifactHash":"` + h + `","ruleId":"r1","version":"1","status":"通过"},
		  {"artifactHash":"` + h + `","ruleId":"r2","version":"1","status":"发现缺陷","note":"bad\uD800"}
		]}`)
	if _, _, _, _, err := ParseAuditInput(doc); err == nil {
		t.Fatal("one bad record among legal siblings must reject the whole submission")
	}
}
EOF
go test ./contractsentinel/ -run TestZZEdgeVariants -v 2>&1 | tail -6; rm contractsentinel/zz_edge_test.go

